const { URLSearchParams } = require('url');

function decode(str) {
  if (typeof str !== 'string') return str;
  return decodeURIComponent(str.replace(/\+/g, ' '));
}

function parseQuery(qs) {
  if (typeof qs !== 'string') return qs;
  qs = qs.replace(/^\?/, '');
  if (!qs) return {};

  const result = {};
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (!pair) continue;
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = decode(pair);
      value = '';
    } else {
      key = decode(pair.slice(0, eqIndex));
      value = decode(pair.slice(eqIndex + 1));
    }

    if (key === '') continue;

    if (result[key] === undefined) {
      result[key] = value;
    } else if (Array.isArray(result[key])) {
      result[key].push(value);
    } else {
      result[key] = [result[key], value];
    }
  }

  return result;
}

function buildQuery(obj) {
  if (obj === null || obj === undefined) return '';
  if (typeof obj !== 'object') return encodeURIComponent(String(obj));

  const parts = [];

  function processKey(key, value) {
    if (value === null || value === undefined) return;

    if (Array.isArray(value)) {
      if (value.length === 0) return;
      if (value.length === 1) {
        processKey(key, value[0]);
        return;
      }
      const encodedKey = encodeURIComponent(key);
      parts.push(value.map(v => `${encodedKey}=${encodeURIComponent(String(v))}`).join('&'));
      return;
    }

    if (typeof value === 'object') {
      const keys = Object.keys(value).sort();
      if (keys.length === 0) return;
      const encodedKey = encodeURIComponent(key);
      const subParts = [];
      for (const k of keys) {
        const v = value[k];
        if (Array.isArray(v)) {
          const arrKey = `${encodedKey}[${encodeURIComponent(String(k))}]`;
          subParts.push(v.map(val => `${arrKey}=${encodeURIComponent(String(val))}`).join('&'));
        } else {
          const nestedKey = `${encodedKey}[${encodeURIComponent(String(k))}]`;
          subParts.push(nestedKey + '=' + encodeURIComponent(String(v)));
        }
      }
      parts.push(subParts.join('&'));
      return;
    }

    const encodedKey = encodeURIComponent(key);
    const encodedValue = encodeURIComponent(String(value));
    parts.push(`${encodedKey}=${encodedValue}`);
  }

  const keys = Object.keys(obj).sort();
  for (const k of keys) {
    processKey(k, obj[k]);
  }

  return parts.join('&');
