        // that a task is waiting for a failed task? No, failed tasks are marked.
        // Actually, if a task depends on a failed task, it won't be in pending? 
        // We mark failed tasks in 'failed' set. 'pending' only has tasks not completed/failed.
        // If a task depends on a failed task, it cannot run.
        // So if queue is empty and running is empty, and there are pending tasks, 
        // it means they are waiting for something that will never happen (cycle or failed dep).
        // Since we checked cycles, it must be a failed dependency chain.
        // But we need to detect the cycle explicitly if the static check missed it?
        // The static check is reliable for the given graph.
        // So this state should not happen unless the graph has a cycle.
        // Let's throw to be safe.
        throw new Error('Dependency cycle detected');
      }

      if (taskQueue.length > 0) {
        const name = taskQueue.shift();
        running.add(name);
        try {
          const config = tasks[name];
          const deps = config.deps || [];
          const depValues = {};

          for (const dep of deps) {
            if (failed.has(dep)) {
              throw errorMap.get(dep);
            }
            depValues[dep] = results.get(dep);
          }

