          results.set(name, val);
          completed.add(name);
          pending.delete(name);
        } catch (err) {
          failed.add(name);
          errorMap.set(name, err);
          // Do not throw here immediately, let the final promise handle it.
          // But we need to stop processing this task.
        } finally {
          running.delete(name);
        }
      }
