    const res = await execute();
    return res;
  } catch (err) {
    // Ensure the error message contains 'cycle' if it's a cycle error
    if (err.message.includes('cycle')) {
      throw err;
    }
    // If it's a missing dep error, ensure it mentions the name
    if (err.message.includes('Unknown dependency')) {
      throw err;
    }
    // If it's a task rejection, re-throw as is
    throw err;
  }
};

