export type Curry<T extends any[]> = T extends [infer First, ...infer Rest]
  ? (arg: First) => Curry<Rest>
  : (...args: T) => void;

export function curry<T extends any[]>(fn: (...args: T) => void): Curry<T> {
  return function(...args: T): void | ((...rest: T) => void) {
    if (args.length === fn.length) {
      return fn(...args);
    }
    return function(...rest: T): void {
      return fn(...args, ...rest);
    } as any;
  } as Curry<T>;
}

