export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RoutePath<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer _}` ? string : never;
}[keyof T];

export type RouteHandler<T extends Record<string, string>> = T extends Record<string, string>
  ? T extends { [K: string]: string }
    ? (params: { [K in keyof T]: string }) => string
    : never
  : () => string;

export type DefinedRoutes<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer _}`
    ? (params: { [P in keyof T]: string }) => string
    : () => string;
};

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): DefinedRoutes<T> {
  const result: DefinedRoutes<T> = {} as DefinedRoutes<T>;

  for (const [name, path] of Object.entries(routes)) {
    const paramKeys = Object.keys(path).filter((_, i) => path[i] && path[i].includes(':'));
    // This is a simplified check; in a real implementation, we would parse the path string
    // to extract exact param names. For this constraint, we rely on the type system
    // to enforce the signature, and a runtime check or a more complex parser would be needed
    // to dynamically generate the correct parameter names from the string template.
    // However, since we cannot use external libraries and must keep it in one file without
    // complex string parsing logic that might be error-prone without regex utilities,
    // we will implement a robust regex-based parser within the function to extract params.

    const paramRegex = /:(\w+)/g;
    const matches = path.match(paramRegex);
    const paramNames = matches ? matches.map((m) => m.slice(1)) : [];

    if (paramNames.length === 0) {
      result[name] = () => path;
    } else {
      result[name] = (params: { [K in typeof paramNames[number]]: string }) => {
        // Runtime check to ensure correct number of params
        if (Object.keys(params).length !== paramNames.length) {
          throw new Error(`Route '${name}' expects ${paramNames.length} parameters, got ${Object.keys(params).length}`);
        }
        let resultPath = path;
        for (const [key, value] of Object.entries(params)) {
          resultPath = resultPath.replace(new RegExp(`:\\${key}`, 'g'), value);
        }
        return resultPath;
      } as any;
    }
  }

  return result;
}

